  "confidence": 0.99,
  "anomalies": [
    {
      "category": "other",
      "components": ["FCC1"],
      "pins": ["FCC1.48", "FCC1.73"],
      "nets": ["UART3_TX_FCC", "UART3_RX_FCC"],
      "observed": "On the FCC sheet, STM32H753 pins 48 and 73, both marked VCAP, are connected to UART3_TX_FCC and UART3_RX_FCC respectively.",
      "expected": "The STM32H753 VCAP pins should each have the required regulator capacitor to ground and must not be used as UART signal pins.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "FCC1: pins 48 and 73 are marked VCAP and connected to UART3_TX_FCC and UART3_RX_FCC. (Flight Control Computer, page 2/6)"
        },
        {
          "source": "spec",
          "quote": "Flight Control Computer MCU | FCC1 | STM32H753VITx"
        }
      ],
      "impact": "The MCU's internal regulator may not operate correctly without the required VCAP capacitors, potentially preventing the FCC from functioning. The UART3 signals are also incorrectly routed to regulator pins, so the debug UART will not work as intended.",
      "confidence": 0.99
    }
  ],
  "summary": "An anomaly is present: the FCC STM32H753 VCAP pins are wired to UART3 signals instead of receiving their required regulator capacitors. This can prevent correct MCU operation and leaves UART3 unusable."
}

